    webSearchSidebars: webSearchSidebars.map(x => ({ className: x.className, visible: visible(x) })),
    expertModeToggles: expertModeToggles.map(x => ({ className: x.className, aria: x.getAttribute('aria-label'), checked: x.getAttribute('aria-checked') })),
    thinkingToggles: thinkingToggles.map(x => ({ className: x.className, aria: x.getAttribute('aria-label'), state: x.getAttribute('data-thinking') })),
    topClasses
  };
});

